-- Version 2 of the four free-text assessment templates (LIA, TIA, PIA, Custom).
--
-- The consultant's point: a regulator reading a registration looks for keywords,
-- and free text hides them. v2 turns every question a regulator reads into a
-- structured one (single/multiple choice, yes-no with a follow-up, a graded
-- select, or a date as an ISO text field), each with per-question help, in the
-- vocabulary of the law. The DPIA is left alone (already structured, v3.0).
--
-- Delivered as NEW template rows, so running assessments keep their v1 template,
-- questions and answers untouched. The four v1 SYSTEM rows are marked superseded
-- so the picker (which already filters supersededAt IS NULL) offers only v2 for
-- NEW assessments. PIA has no v1 row, so nothing is superseded for it.
--
-- Question text is stored in English; the Spanish lives in the message bundles
-- (templates.<type>.…), matched by position, exactly as every other template.
--
-- ADDITIVE ONLY and idempotent: INSERT ... ON CONFLICT ("id") DO NOTHING, and the
-- supersede UPDATE is guarded on supersededAt IS NULL so a re-run never moves the
-- date. No table, column, type or row is dropped, renamed, retyped or deleted.

INSERT INTO "assessment_templates"
  ("id", "organizationId", "type", "name", "description", "version", "sections", "scoringLogic", "isSystem", "isActive", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-lia-template-v2', NULL, 'LIA'::"AssessmentType", 'Legitimate Interest Assessment', 'The three-part legitimate interest test of GDPR Article 6(1)(f) (purpose, necessity and balancing), with structured answers a regulator can read. This template is informational, not legal advice; verify with qualified counsel.', '2.0', '[{"id":"liav2_s1","title":"Purpose test","description":"Identify the legitimate interest being pursued.","questions":[{"id":"liav2_1_1","text":"Whose legitimate interest is being pursued?","type":"select","required":true,"helpText":"The interest may be the controller''s or a third party''s. Say whose it is, because the balancing test weighs it against the individual''s rights. Example: \"Our own interest in preventing fraud.\" Source: GDPR Art. 6(1)(f).","options":["Our own interest","A third party''s interest","Both ours and a third party''s"]},{"id":"liav2_1_2","text":"Describe the legitimate interest precisely.","type":"textarea","required":true,"helpText":"Name a specific interest, not just \"business purposes\". A clearly articulated, real and present interest is the first thing the test requires. Example: \"Detecting fraudulent transactions to protect customers and the business.\" Source: GDPR Art. 6(1)(f) and Recital 47."},{"id":"liav2_1_3","text":"Is the interest lawful, clearly articulated and real (not speculative)?","type":"select","required":true,"helpText":"An interest can only be relied on if it is lawful, precise enough to weigh, and a real interest rather than a hypothetical one. Example: \"Yes: fraud prevention is lawful, specific and ongoing.\" Source: GDPR Art. 6(1)(f); EDPB guidance on legitimate interest.","options":["Yes, on all three","Partly","No"]}]},{"id":"liav2_s2","title":"Necessity test","description":"Assess whether the processing is necessary for that interest.","questions":[{"id":"liav2_2_1","text":"Is the processing necessary to achieve the interest?","type":"select","required":true,"helpText":"\"Necessary\" means the processing is a targeted and proportionate way to meet the interest, not merely useful. If it is only convenient, legitimate interest is not the right basis. Example: \"Reasonably necessary: fraud scoring needs the transaction data.\" Source: GDPR Art. 6(1)(f).","options":["Essential","Reasonably necessary","Convenient but not necessary","Not necessary"]},{"id":"liav2_2_2","text":"Could a less intrusive means achieve the same result?","type":"select","required":true,"helpText":"If a less intrusive way exists that is reasonably effective, you should use it instead. Example: \"No: aggregated data would miss the individual fraud patterns.\" Source: GDPR Art. 6(1)(f); principle of data minimisation, Art. 5(1)(c).","options":["No, this is the least intrusive means","A less intrusive means exists but is far less effective","A less intrusive means is available"]},{"id":"liav2_2_3","text":"Is the data limited to what the interest requires (data minimisation)?","type":"boolean","required":true,"helpText":"Only the data genuinely needed for the interest should be processed. Example: \"Yes: we use the transaction and device data, not the full customer profile.\" Source: GDPR Art. 5(1)(c)."}]},{"id":"liav2_s3","title":"Balancing test","description":"Weigh the interest against the individual''s rights and freedoms.","questions":[{"id":"liav2_3_1","text":"What is the nature of the data?","type":"select","required":true,"helpText":"The more sensitive the data, the heavier it weighs against the interest. Special category and criminal-offence data need a separate condition and rarely sit under legitimate interest alone. Example: \"No special category data.\" Source: GDPR Arts. 9 and 10.","options":["No special category or criminal-offence data","Sensitive but not special category","Includes special category or criminal-offence data"]},{"id":"liav2_3_2","text":"Would data subjects reasonably expect this processing?","type":"select","required":true,"helpText":"Reasonable expectations turn on the relationship and how the data was collected. The less expected, the harder the interest is to justify. Example: \"Clearly expected: customers expect fraud checks on payments.\" Source: GDPR Recital 47.","options":["Clearly expected","Probably expected","Possibly unexpected","Would not expect it"]},{"id":"liav2_3_3","text":"What is the likely impact on the individual?","type":"select","required":true,"helpText":"Consider the effect on the person, including any decision made about them. A significant negative impact usually tips the balance towards their rights. Example: \"Minor: a flagged payment may be delayed briefly.\" Source: GDPR Art. 6(1)(f).","options":["Positive or neutral","Minor negative","Moderate negative","Significant negative"]},{"id":"liav2_3_4","text":"Are children or other vulnerable people affected?","type":"boolean","required":true,"helpText":"Children and vulnerable people warrant extra weight on their side of the balance. Example: \"No: the service is for account holders aged 18 and over.\" Source: GDPR Recital 38; Art. 6(1)(f)."},{"id":"liav2_3_5","text":"What is the overall balance?","type":"select","required":true,"helpText":"State the conclusion of the balance, taking the safeguards below into account. Where rights prevail, choose another lawful basis. Example: \"Balanced; the right to object and data minimisation are decisive.\" Source: GDPR Art. 6(1)(f).","options":["The interest prevails","Balanced; safeguards are decisive","The individual''s rights prevail (do not rely on legitimate interest)"]}]},{"id":"liav2_s4","title":"Safeguards and outcome","description":"Record the safeguards that protect data subjects and the conclusion.","questions":[{"id":"liav2_4_1","text":"Which safeguards protect data subjects?","type":"multiselect","required":true,"helpText":"Safeguards can tip a finely balanced case in favour of the interest. List the ones actually in place. Example: \"Right to object honoured, retention limits, pseudonymisation.\" Source: GDPR Arts. 21 and 5(1); Recital 47.","options":["The right to object is honoured","Data minimisation","Retention limits","Access controls","Pseudonymisation","Transparency in the privacy notice","Regular review"]},{"id":"liav2_4_2","text":"Have you told individuals about this processing and their right to object?","type":"boolean","required":true,"helpText":"Individuals must be told, in the privacy notice, that you rely on legitimate interest and that they can object. Example: \"Yes: the privacy notice names the interest and explains how to object.\" Source: GDPR Arts. 13(1)(d), 14(2)(b) and 21."},{"id":"liav2_4_3","text":"Conclusion and any conditions.","type":"textarea","required":false,"helpText":"Summarise the outcome and any conditions that must hold for the processing to remain justified. Example: \"May proceed while the right to object is honoured and retention stays at 12 months.\" Source: GDPR Art. 6(1)(f)."}]}]'::jsonb, '{"method":"weighted_average","riskLevels":{"LOW":{"min":0,"max":25},"MEDIUM":{"min":26,"max":50},"HIGH":{"min":51,"max":75},"CRITICAL":{"min":76,"max":100}}}'::jsonb, true, true, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "assessment_templates"
  ("id", "organizationId", "type", "name", "description", "version", "sections", "scoringLogic", "isSystem", "isActive", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-tia-template-v2', NULL, 'TIA'::"AssessmentType", 'Transfer Impact Assessment', 'Assess a transfer of personal data to a third country and whether supplementary measures are needed for an essentially equivalent level of protection (EDPB Recommendations 01/2020, Schrems II), with structured answers. Informational, not legal advice; verify with qualified counsel.', '2.0', '[{"id":"tiav2_s1","title":"The transfer","description":"Describe the transfer, its tool, the data and the parties.","questions":[{"id":"tiav2_1_1","text":"Which transfer tool are you relying on?","type":"select","required":true,"helpText":"The transfer tool is the legal basis for sending the data abroad. Where an adequacy decision covers the destination, no supplementary measures are needed. Example: \"Standard Contractual Clauses.\" Source: GDPR Arts. 45 to 49.","options":["Adequacy decision (Art. 45)","Standard Contractual Clauses (Art. 46)","Binding Corporate Rules (Art. 47)","Derogation for a specific situation (Art. 49)","Other Article 46 safeguard"]},{"id":"tiav2_1_2","text":"Which SCC module applies?","type":"select","required":true,"helpText":"The 2021 Standard Contractual Clauses have four modules for the roles of the exporter and importer. Pick the one that matches. Example: \"Module 2: we are the controller, the importer is our processor.\" Source: Commission Implementing Decision (EU) 2021/914.","options":["Module 1: controller to controller","Module 2: controller to processor","Module 3: processor to processor","Module 4: processor to controller"],"showIf":{"questionId":"tiav2_1_1","anyOf":["Standard Contractual Clauses (Art. 46)"]}},{"id":"tiav2_1_3","text":"What categories of personal data are transferred?","type":"multiselect","required":true,"helpText":"The sensitivity and volume of the data drive the risk of the transfer. Name every category, because special category and criminal-offence data raise the bar. Example: \"Contact details, identifiers, behavioural data.\" Source: EDPB Recommendations 01/2020, step 1.","options":["Contact details","Identifiers","Financial data","Behavioural or usage data","Location data","Special category data","Criminal-offence data"]},{"id":"tiav2_1_4","text":"Who is the exporter and who is the importer, and in which countries?","type":"textarea","required":true,"helpText":"Name the organisations, their roles (controller or processor) and the countries of establishment, so the transfer is fully mapped. Example: \"We (controller, Spain) to our hosting provider (processor, United States).\" Source: EDPB Recommendations 01/2020, step 1."},{"id":"tiav2_1_5","text":"Is the data onward-transferred to a further third country?","type":"boolean","required":true,"helpText":"An onward transfer to a further country extends the chain of risk and must itself be covered. Example: \"Yes: the importer uses a sub-processor in a third country.\" Source: EDPB Recommendations 01/2020."}]},{"id":"tiav2_s2","title":"Destination laws and practices","description":"Assess whether the destination gives essentially equivalent protection.","questions":[{"id":"tiav2_2_1","text":"Does the destination country have an EU adequacy decision?","type":"select","required":true,"helpText":"Adequacy means the Commission has found the country''s protection essentially equivalent. Without it, you must assess the laws and practices yourself. Example: \"No adequacy decision.\" Source: GDPR Art. 45.","options":["Yes, full adequacy","Yes, partial adequacy","No adequacy decision","Adequacy under review or challenged"]},{"id":"tiav2_2_2","text":"Does the destination''s law allow disproportionate government access to data?","type":"select","required":true,"helpText":"The core Schrems II question: can public authorities reach the data in ways that would not be acceptable in the EU? Name the laws. Example: \"Broad surveillance powers: FISA Section 702 and EO 12333.\" Source: EDPB Recommendations 01/2020, step 3.","options":["No known access legislation","Access exists but with effective oversight and safeguards","Broad surveillance powers with limited oversight","Mass surveillance or no independent judicial oversight"]},{"id":"tiav2_2_3","text":"Is the importer subject to government access requests in practice?","type":"select","required":true,"helpText":"Law on the books matters less if it is not applied to this importer; but a real risk in the sector counts against the transfer. Example: \"Possible: cloud providers are within scope of the access law.\" Source: EDPB Recommendations 01/2020, step 3.","options":["No: never received such a request","Possible: operates in a sector that may be targeted","Yes: transparency reports confirm requests","Unknown"]},{"id":"tiav2_2_4","text":"Are effective legal remedies available to EU data subjects there?","type":"select","required":true,"helpText":"Essentially equivalent protection includes a real way for individuals to challenge access to their data. Example: \"Partial: an ombudsperson mechanism but no court review.\" Source: EDPB Recommendations 01/2020, step 3; GDPR Art. 47 of the Charter.","options":["Yes: independent judicial review","Partial: administrative remedies only","No effective remedies","Unknown"]},{"id":"tiav2_2_5","text":"Describe the relevant laws and government access practices.","type":"textarea","required":true,"helpText":"Cite specific legislation and any public government-access or transparency reports. Example: \"FISA Section 702 permits access to data held by electronic communication service providers; the importer''s transparency report shows N requests.\" Source: EDPB Recommendations 01/2020, step 3."}]},{"id":"tiav2_s3","title":"Supplementary measures","description":"Identify measures that supplement the transfer tool.","questions":[{"id":"tiav2_3_1","text":"Which technical measures are in place?","type":"multiselect","required":true,"helpText":"Effective encryption with keys held outside the destination is the strongest technical safeguard against government access. Example: \"Encryption at rest with EU-held keys and pseudonymisation.\" Source: EDPB Recommendations 01/2020, Annex 2.","options":["Encryption at rest, importer cannot access the keys","Encryption in transit (TLS 1.2 or higher)","End-to-end encryption, exporter-held keys only","Pseudonymisation before transfer","Anonymisation or aggregation before transfer","Split processing across parties","None"]},{"id":"tiav2_3_2","text":"Which contractual measures supplement the transfer tool?","type":"multiselect","required":true,"helpText":"Contract terms bind the importer to resist and report access and to let the exporter act. Example: \"Duty to challenge and to notify, plus a suspension clause.\" Source: EDPB Recommendations 01/2020, Annex 2; SCC clause 15.","options":["Duty to challenge government access requests","Duty to notify the exporter of access (where lawful)","Transparency reporting obligation","No onward transfer without prior authorisation","Audit rights for the exporter","Data localisation obligation","Suspension or termination if the law changes","None"]},{"id":"tiav2_3_3","text":"Which organisational measures are in place?","type":"multiselect","required":true,"helpText":"Organisational measures back up the technical and contractual ones with people and procedures. Example: \"A documented access-request policy and annual ISO 27001 certification.\" Source: EDPB Recommendations 01/2020, Annex 2.","options":["Internal policy for responding to access requests","Staff training on data protection","A designated privacy or compliance team at the importer","Recognised certifications (ISO 27001, SOC 2)","Incident response plan covering access scenarios","None"]},{"id":"tiav2_3_4","text":"Are the measures effective against the identified risks? Explain.","type":"textarea","required":true,"helpText":"Explain why the measures together do, or do not, bring the protection up to an essentially equivalent level. If the importer must access the data in the clear, encryption may not help against an access order. Example: \"Effective: data is pseudonymised and keys stay in the EU.\" Source: EDPB Recommendations 01/2020, step 4."}]},{"id":"tiav2_s4","title":"Risk and conclusion","description":"Weigh the residual risk and decide whether the transfer can proceed.","questions":[{"id":"tiav2_4_1","text":"How likely is government access to the transferred data?","type":"select","required":true,"helpText":"Combine the destination''s laws and practices with the data type and the safeguards. Example: \"Low: pseudonymised data, keys in the EU, sector not routinely targeted.\" Source: EDPB Recommendations 01/2020, step 3.","options":["Negligible","Low","Medium","High"]},{"id":"tiav2_4_2","text":"How severe would the impact on data subjects be if accessed?","type":"select","required":true,"helpText":"Weigh the harm to individuals if their data were accessed, given its sensitivity. Example: \"Medium: identifiable contact and usage data.\" Source: EDPB Recommendations 01/2020, step 3.","options":["Negligible","Low","Medium","High"]},{"id":"tiav2_4_3","text":"Can the transfer proceed?","type":"select","required":true,"helpText":"The overall conclusion of the assessment. Where the risk cannot be brought down, the transfer should not proceed on this tool. Example: \"Yes, with conditions: implement EU-held keys first.\" Source: EDPB Recommendations 01/2020, step 6.","options":["Yes: essentially equivalent protection","Yes, with conditions","No: residual risk too high, suspend or find another route"]},{"id":"tiav2_4_4","text":"If conditions are required, describe them.","type":"textarea","required":false,"helpText":"List the specific actions that must be completed before or during the transfer. Example: \"Move key management to the EU; add a suspension clause to the contract.\" Source: EDPB Recommendations 01/2020, step 6."}]},{"id":"tiav2_s5","title":"Re-evaluation","description":"Define how the transfer is monitored and when it is reviewed.","questions":[{"id":"tiav2_5_1","text":"Which events should trigger a re-assessment?","type":"multiselect","required":true,"helpText":"A transfer assessment is not one-off: name the events that reopen it. Example: \"New access legislation; any access request; a 12-month review.\" Source: EDPB Recommendations 01/2020, step 6.","options":["New legislation or executive order in the destination","Adequacy decision revoked or challenged","The importer receives a government access request","Change in data categories or volume","Change of sub-processor or onward transfer","Periodic review (at least every 12 months)","Supervisory authority guidance or enforcement"]},{"id":"tiav2_5_2","text":"When is the next scheduled review?","type":"text","required":true,"helpText":"Give a specific date, in the form YYYY-MM-DD. Example: \"2027-04-01.\" Source: EDPB Recommendations 01/2020, step 6."}]}]'::jsonb, '{"method":"weighted_average","riskLevels":{"LOW":{"min":0,"max":25},"MEDIUM":{"min":26,"max":50},"HIGH":{"min":51,"max":75},"CRITICAL":{"min":76,"max":100}}}'::jsonb, true, true, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "assessment_templates"
  ("id", "organizationId", "type", "name", "description", "version", "sections", "scoringLogic", "isSystem", "isActive", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-pia-template-v2', NULL, 'PIA'::"AssessmentType", 'Privacy Impact Assessment', 'A broad privacy review of a processing activity: the data, the purposes, the lawful basis, retention, recipients, the rights of individuals and security, with structured answers. Informational, not legal advice; verify with qualified counsel.', '2.0', '[{"id":"piav2_s1","title":"The processing","description":"Describe what is processed, why and about whom.","questions":[{"id":"piav2_1_1","text":"What is the purpose of the processing?","type":"textarea","required":true,"helpText":"State the specific, explicit purpose, which every later question is measured against. Example: \"Managing customer orders and after-sales support.\" Source: GDPR Art. 5(1)(b)."},{"id":"piav2_1_2","text":"What categories of personal data are processed?","type":"multiselect","required":true,"helpText":"List every category, because the categories drive the risk and the obligations. Example: \"Contact details, identifiers, financial data.\" Source: GDPR Art. 30(1)(c).","options":["Contact details","Identifiers","Financial data","Behavioural or usage data","Location data","Special category data","Criminal-offence data"]},{"id":"piav2_1_3","text":"Does the processing involve special category or criminal-offence data?","type":"boolean","required":true,"helpText":"Special category data (Art. 9) and criminal-offence data (Art. 10) need a specific condition beyond the lawful basis. Example: \"No.\" Source: GDPR Arts. 9 and 10."},{"id":"piav2_1_4","text":"Which Article 9(2) or Article 10 condition applies?","type":"textarea","required":false,"helpText":"Name the specific condition that permits the special category or criminal-offence data. Example: \"Explicit consent (Art. 9(2)(a)).\" Source: GDPR Arts. 9(2) and 10.","showIf":{"questionId":"piav2_1_3","anyOf":["Yes"]}},{"id":"piav2_1_5","text":"Who are the data subjects?","type":"multiselect","required":true,"helpText":"Name the groups whose data is processed. Children and vulnerable people call for extra care. Example: \"Customers and website users.\" Source: GDPR Art. 30(1)(c); Recital 38.","options":["Customers","Employees","Job applicants","Suppliers or contacts","Website or app users","Children","Other vulnerable people"]}]},{"id":"piav2_s2","title":"Lawful basis and retention","description":"Record the lawful basis and how long the data is kept.","questions":[{"id":"piav2_2_1","text":"What is the lawful basis for the processing?","type":"select","required":true,"helpText":"Every processing needs one of the six lawful bases, chosen before processing begins. Legitimate interest also needs a balancing test (the LIA template). Example: \"Contract.\" Source: GDPR Art. 6(1).","options":["Consent (Art. 6(1)(a))","Contract (Art. 6(1)(b))","Legal obligation (Art. 6(1)(c))","Vital interests (Art. 6(1)(d))","Public task (Art. 6(1)(e))","Legitimate interests (Art. 6(1)(f))"]},{"id":"piav2_2_2","text":"How long is the data kept, and from when?","type":"text","required":true,"helpText":"State a retention period and its starting point, not \"as long as necessary\". Example: \"6 years from the end of the contract, for tax law.\" Source: GDPR Art. 5(1)(e)."},{"id":"piav2_2_3","text":"Is the retention period justified and enforced?","type":"boolean","required":true,"helpText":"The period must be justified by the purpose or a legal duty, and the data actually deleted or anonymised at the end. Example: \"Yes: annual deletion job removes expired records.\" Source: GDPR Art. 5(1)(e)."}]},{"id":"piav2_s3","title":"Recipients and transfers","description":"Record who receives the data and any transfer abroad.","questions":[{"id":"piav2_3_1","text":"Who receives the data?","type":"multiselect","required":true,"helpText":"Name every category of recipient, because each adds obligations and risk. Example: \"Internal teams and a hosting processor.\" Source: GDPR Art. 30(1)(d).","options":["Internal teams only","Processors acting on our behalf","Joint controllers","Other controllers","Public authorities"]},{"id":"piav2_3_2","text":"Is every processor bound by a written data processing agreement (Art. 28)?","type":"boolean","required":true,"helpText":"A processor may only act under a contract with the terms Article 28 requires. Example: \"Yes: a signed DPA is in place with each processor.\" Source: GDPR Art. 28(3)."},{"id":"piav2_3_3","text":"Is any data transferred outside the EU or EEA?","type":"boolean","required":true,"helpText":"A transfer to a third country needs a transfer tool and, outside adequacy, a Transfer Impact Assessment (the TIA template). Example: \"Yes: our hosting provider is in the United States.\" Source: GDPR Arts. 44 to 49."},{"id":"piav2_3_4","text":"Which transfer tool covers it, and is a TIA in place?","type":"text","required":false,"helpText":"Name the transfer tool and whether a Transfer Impact Assessment has been done. Example: \"Standard Contractual Clauses; TIA completed 2026-05.\" Source: GDPR Arts. 46 and 44.","showIf":{"questionId":"piav2_3_3","anyOf":["Yes"]}}]},{"id":"piav2_s4","title":"Rights and transparency","description":"Record how individuals are informed and how their rights are met.","questions":[{"id":"piav2_4_1","text":"Have individuals been given the privacy information required by Articles 13-14?","type":"boolean","required":true,"helpText":"People must be told who processes their data, why, on what basis, for how long and what rights they have. Example: \"Yes: a layered privacy notice at the point of collection.\" Source: GDPR Arts. 13 and 14."},{"id":"piav2_4_2","text":"Which data subject rights are supported?","type":"multiselect","required":true,"helpText":"You must be able to honour the rights that apply to your basis and processing. Example: \"Access, rectification, erasure and objection.\" Source: GDPR Arts. 15 to 22.","options":["Access (Art. 15)","Rectification (Art. 16)","Erasure (Art. 17)","Restriction (Art. 18)","Portability (Art. 20)","Objection (Art. 21)"]},{"id":"piav2_4_3","text":"Is there solely automated decision-making with legal or similarly significant effects?","type":"boolean","required":true,"helpText":"Decisions made solely by automated means with a legal or similarly significant effect are restricted and need specific safeguards. Example: \"No: a person reviews every decision.\" Source: GDPR Art. 22."},{"id":"piav2_4_4","text":"What safeguards apply to the automated decision-making?","type":"textarea","required":false,"helpText":"Describe the lawful ground and the safeguards: the right to human intervention, to express a view and to contest the decision. Example: \"Explicit consent; the person can request a human review.\" Source: GDPR Art. 22(3).","showIf":{"questionId":"piav2_4_3","anyOf":["Yes"]}}]},{"id":"piav2_s5","title":"Security and outcome","description":"Record the security measures and the overall privacy risk.","questions":[{"id":"piav2_5_1","text":"Which security measures protect the data (Art. 32)?","type":"multiselect","required":true,"helpText":"Measures must be appropriate to the risk, covering confidentiality, integrity, availability and resilience. Example: \"Encryption, access controls, backups and logging.\" Source: GDPR Art. 32.","options":["Encryption","Pseudonymisation","Access controls","Logging and monitoring","Backups and recovery","Staff training","Regular testing of measures"]},{"id":"piav2_5_2","text":"What is the overall privacy risk after these measures?","type":"select","required":true,"helpText":"Give the residual risk once the measures are in place. A high residual risk points to a full DPIA and possibly prior consultation. Example: \"Low.\" Source: GDPR Arts. 35 and 36.","options":["Low","Medium","High"]},{"id":"piav2_5_3","text":"What residual actions or recommendations remain?","type":"textarea","required":false,"helpText":"Note any follow-up needed to reduce the risk further or to keep the assessment current. Example: \"Schedule a DPIA if profiling is added.\" Source: GDPR Art. 35(1)."}]}]'::jsonb, '{"method":"weighted_average","riskLevels":{"LOW":{"min":0,"max":25},"MEDIUM":{"min":26,"max":50},"HIGH":{"min":51,"max":75},"CRITICAL":{"min":76,"max":100}}}'::jsonb, true, true, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "assessment_templates"
  ("id", "organizationId", "type", "name", "description", "version", "sections", "scoringLogic", "isSystem", "isActive", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-custom-template-v2', NULL, 'CUSTOM'::"AssessmentType", 'Custom Assessment', 'A flexible assessment for custom privacy reviews, with a structured risk answer and room for a written rationale. Informational, not legal advice; verify with qualified counsel.', '2.0', '[{"id":"customv2_s1","title":"Overview","description":"Describe the scope and purpose of this assessment.","questions":[{"id":"customv2_1_1","text":"What is the purpose of this assessment?","type":"textarea","required":true,"helpText":"Say what you are evaluating and why, so the reader knows the scope. Example: \"Reviewing a new marketing analytics tool before launch.\" Source: GDPR Art. 24 (accountability)."},{"id":"customv2_1_2","text":"What is the scope of this assessment?","type":"textarea","required":true,"helpText":"Define the systems, processes or data flows in scope, and anything left out. Example: \"The web analytics pipeline; excludes the CRM.\" Source: GDPR Art. 24."}]},{"id":"customv2_s2","title":"Risk evaluation","description":"Identify the key risks and rate them.","questions":[{"id":"customv2_2_1","text":"What are the key risks identified?","type":"textarea","required":true,"helpText":"Name the concrete risks to individuals or to compliance, not generic ones. Example: \"Tracking without consent; over-collection of behavioural data.\" Source: GDPR Art. 24."},{"id":"customv2_2_2","text":"What is the overall risk level?","type":"select","required":true,"helpText":"Give a single overall rating for the risks above, before mitigation. Example: \"Medium.\" Source: GDPR Art. 24.","options":["Low","Medium","High","Critical"]}]},{"id":"customv2_s3","title":"Mitigations and recommendations","description":"Record the mitigations and the residual position.","questions":[{"id":"customv2_3_1","text":"What mitigations are in place or recommended?","type":"textarea","required":true,"helpText":"List the measures that reduce the risks and who owns them. Example: \"Consent banner before any tracking; retention capped at 14 months.\" Source: GDPR Art. 24."},{"id":"customv2_3_2","text":"Is the residual risk acceptable?","type":"select","required":true,"helpText":"State whether the risk that remains after mitigation is acceptable, and under what conditions. Example: \"Acceptable with conditions: launch after the consent banner is live.\" Source: GDPR Art. 24.","options":["Yes, fully acceptable","Acceptable with conditions","Needs further review","Not acceptable"]}]}]'::jsonb, '{"method":"weighted_average","riskLevels":{"LOW":{"min":0,"max":25},"MEDIUM":{"min":26,"max":50},"HIGH":{"min":51,"max":75},"CRITICAL":{"min":76,"max":100}}}'::jsonb, true, true, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

-- Retire the v1 SYSTEM templates for NEW assessments only. Guarded on
-- supersededAt IS NULL so a re-run never moves the date, and scoped to the known
-- ids, isSystem and organizationId IS NULL so no org-authored template is touched.
UPDATE "assessment_templates"
SET "supersededAt" = NOW()
WHERE "id" IN ('system-lia-template', 'system-tia-template', 'system-pia-template', 'system-custom-template')
  AND "isSystem" = true
  AND "organizationId" IS NULL
  AND "supersededAt" IS NULL;
